using Invoklet.Contracts.Connections;
using Invoklet.Format.MdRun;
using Invoklet.NonUI.Tests.Contracts.Connections.Fixtures;
using Xunit;

namespace Invoklet.NonUI.Tests.Contracts.Connections;

// The code Invoklet adds to a script's build for its connections: the Connections class, and the files of the schemas read.
[Trait("Platform", "Independent")]
public sealed class GeneratedConnectionsTests
{
    // The wrapper isn't generated by a tool: it keeps the full nullable context its annotations need (CS8669 otherwise).
    [Fact]
    public void For_AConnection_WrapsTheSourceInAFullNullableContext()
    {
        // Arrange
        var fixture = new GeneratedConnectionsFixture();
        var connection = GeneratedConnectionsFixture.Connection("inventory");
        fixture.HasSchema(connection);

        // Act
        var generated = GeneratedConnections.For([connection], MdRunLanguage.CSharp, [], fixture.Drivers(), fixture.Schemas.Object)!;

        // Assert
        Assert.StartsWith("#nullable enable\n", generated.Source, StringComparison.Ordinal);
        Assert.EndsWith("#nullable restore\n", generated.Source, StringComparison.Ordinal);
        Assert.DoesNotContain("#nullable enable annotations", generated.Source, StringComparison.Ordinal);
    }

    // Two connections to servers with the same schema file share it: it is compiled once.
    [Fact]
    public void For_TwoConnectionsWithTheSameSchemaFile_AddItOnce()
    {
        // Arrange
        var fixture = new GeneratedConnectionsFixture();
        var first = GeneratedConnectionsFixture.Connection("inventory");
        var second = GeneratedConnectionsFixture.Connection("other");
        var shared = new GeneratedSourceFile("Shared.cs", "namespace Shared { public partial class Message { } }");
        fixture.HasSchema(first, shared);
        fixture.HasSchema(second, shared);

        // Act
        var generated = GeneratedConnections.For([first, second], MdRunLanguage.CSharp, [], fixture.Drivers(), fixture.Schemas.Object)!;

        // Assert
        Assert.Empty(generated.Errors);
        Assert.Equal(["Inventory.Shared.cs"], generated.Files.Select(f => f.Name));
    }

    [Fact]
    public void For_TwoConnectionsWithDifferentFilesOfOneName_SaysTheyConflict()
    {
        // Arrange
        var fixture = new GeneratedConnectionsFixture();
        var first = GeneratedConnectionsFixture.Connection("inventory");
        var second = GeneratedConnectionsFixture.Connection("other");
        fixture.HasSchema(first, new GeneratedSourceFile("Shared.cs", "namespace Shared { public partial class Message { public void Send() {} } }"));
        fixture.HasSchema(second, new GeneratedSourceFile("Shared.cs", "namespace Shared { public partial class Message { public void Receive() {} } }"));

        // Act
        var generated = GeneratedConnections.For([first, second], MdRunLanguage.CSharp, [], fixture.Drivers(), fixture.Schemas.Object)!;

        // Assert
        Assert.Equal(["Connection 'other': its schema file 'Shared.cs' conflicts with another connection's schema."], generated.Errors);
    }

    [Fact]
    public void For_ASchemaNotReadYet_SaysWhenItWillBe()
    {
        // Arrange
        var fixture = new GeneratedConnectionsFixture();
        var connection = GeneratedConnectionsFixture.Connection("inventory");

        // Act
        var generated = GeneratedConnections.For([connection], MdRunLanguage.CSharp, [], fixture.Drivers(), fixture.Schemas.Object)!;

        // Assert
        Assert.Equal(["Connection 'inventory': its description hasn't been read yet; Invoklet reads it when the script is opened or run."],
            generated.Errors);
    }

    [Fact]
    public void For_ASchemaThatCouldNotBeRead_SaysWhy()
    {
        // Arrange
        var fixture = new GeneratedConnectionsFixture();
        var connection = GeneratedConnectionsFixture.Connection("inventory");
        fixture.CouldNotRead(connection, "The server doesn't offer gRPC server reflection.");

        // Act
        var generated = GeneratedConnections.For([connection], MdRunLanguage.CSharp, [], fixture.Drivers(), fixture.Schemas.Object)!;

        // Assert
        Assert.Equal(["Connection 'inventory': its description couldn't be read: The server doesn't offer gRPC server reflection."],
            generated.Errors);
    }
}
